import { constants } from "node:fs";
import {
  link,
  lstat,
  mkdir,
  open,
  readFile,
  realpath,
  rename,
  rm,
  rmdir,
} from "node:fs/promises";
import {
  dirname,
  isAbsolute,
  join,
  parse,
  relative,
  resolve,
  sep,
} from "node:path";
import { randomUUID } from "node:crypto";
import { defineRuntimeConfig, type RuntimeConfig } from "./config.js";
import { appendMissingEnv } from "./dotenv.js";
export const MARKER =
  "// AUTO-GENERATED BY @serggrey1992/next-runtime-env\n// DO NOT EDIT MANUALLY\n";
export interface GenerateOptions {
  cwd: string;
  envOnly?: boolean;
  codeOnly?: boolean;
  env?: readonly string[];
  allowOutsideRoot?: boolean;
}
interface Change {
  path: string;
  before: Buffer | undefined;
  after: Buffer;
  env: boolean;
  mode: number;
}
export async function checkPath(
  path: string,
  root: string,
  allowOutside: boolean,
): Promise<void> {
  const rel = relative(root, path);
  if (
    !allowOutside &&
    (rel === ".." || rel.startsWith(`..${sep}`) || isAbsolute(rel))
  )
    throw new Error("Refusing to write outside project root");
  let cursor = parse(path).root;
  for (const part of path.slice(cursor.length).split(sep).filter(Boolean)) {
    cursor = join(cursor, part);
    try {
      const info = await lstat(cursor);
      if (info.isSymbolicLink())
        throw new Error(`Refusing symlink path: ${cursor}`);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    }
  }
}
export async function existing(path: string): Promise<Buffer | undefined> {
  try {
    const info = await lstat(path);
    if (!info.isFile()) throw new Error(`Expected regular file: ${path}`);
    if (info.nlink > 1)
      throw new Error(`Refusing hardlink destination: ${path}`);
    return await readFile(path);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw error;
  }
}
function moduleSource(
  keys: readonly string[],
  section: "client" | "server",
): string {
  const method = section === "client" ? "getPublicEnv" : "getServerEnv";
  return `${MARKER}\n${section === "server" ? "import 'server-only';\n\n" : ""}import { ${method} } from '@serggrey1992/next-runtime-env/${section}';\n\nexport const env = {\n${keys.map((key) => `  get ${key}(): string | undefined {\n    return ${method}('${key}');\n  },`).join("\n\n")}\n};\n`;
}
export async function generate(
  input: RuntimeConfig,
  options: GenerateOptions,
): Promise<readonly string[]> {
  if (options.envOnly && options.codeOnly)
    throw new Error("--env-only and --code-only cannot be combined");
  const config = defineRuntimeConfig(input);
  const root = await realpath(resolve(options.cwd));
  let files = [...config.envFiles];
  if (options.env) {
    files = options.env.map((name) =>
      name === "default"
        ? ".env"
        : name.startsWith(".env")
          ? name
          : `.env.${name}`,
    );
    if (files.some((file) => !config.envFiles.includes(file)))
      throw new Error("--env must select configured envFiles");
    files = [...new Set(files)];
  }
  const planned: { path: string; source?: string; env: boolean }[] = [];
  if (!options.envOnly)
    for (const section of ["client", "server"] as const)
      planned.push({
        path: resolve(root, config.output, `${section}.ts`),
        source: moduleSource(
          config[section === "client" ? "public" : "server"],
          section,
        ),
        env: false,
      });
  if (!options.codeOnly)
    for (const file of files)
      planned.push({ path: resolve(root, file), env: true });
  const changes: Change[] = [];
  // Validate and read EVERY destination before the first filesystem mutation.
  for (const item of planned) {
    await checkPath(item.path, root, options.allowOutsideRoot ?? false);
    const before = await existing(item.path);
    if (!item.env && before && !before.toString("utf8").startsWith(MARKER))
      throw new Error(`Refusing to overwrite user TypeScript: ${item.path}`);
    if (before && !Buffer.from(before.toString("utf8")).equals(before))
      throw new Error(`Invalid UTF-8 file: ${item.path}`);
    const after = Buffer.from(
      item.env
        ? appendMissingEnv(before?.toString("utf8") ?? "", [
            ...config.public,
            ...config.server,
          ])
        : item.source!,
    );
    if (before?.equals(after)) continue;
    const mode = before ? (await lstat(item.path)).mode & 0o777 : 0o600;
    changes.push({ path: item.path, before, after, env: item.env, mode });
  }
  const applied: Change[] = [];
  const dirs: string[] = [];
  const temps: string[] = [];
  try {
    for (const change of changes) {
      await checkPath(change.path, root, options.allowOutsideRoot ?? false);
      const now = await existing(change.path);
      if (change.before ? !now?.equals(change.before) : now !== undefined)
        throw new Error("Destination changed during generation; retry");
      let parent = dirname(change.path);
      const missing: string[] = [];
      while (true) {
        try {
          await lstat(parent);
          break;
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
          missing.unshift(parent);
          parent = dirname(parent);
        }
      }
      for (const dir of missing) {
        await mkdir(dir);
        dirs.push(dir);
      }
      if (change.env && change.before) {
        // Append only: preserve inode, bytes, permissions, quotes and line endings.
        const handle = await open(
          change.path,
          constants.O_WRONLY | constants.O_APPEND | constants.O_NOFOLLOW,
        );
        applied.push(change);
        try {
          await handle.writeFile(change.after.subarray(change.before.length));
          await handle.sync();
        } finally {
          await handle.close();
        }
      } else {
        const temp = `${change.path}.${randomUUID()}.tmp`;
        temps.push(temp);
        const handle = await open(temp, "wx", change.mode);
        try {
          await handle.writeFile(change.after);
          await handle.sync();
        } finally {
          await handle.close();
        }
        if (change.before) {
          await rename(temp, change.path);
        } else {
          // Atomic, exclusive install of a fully written temporary inode.
          await link(temp, change.path);
          applied.push(change);
          await rm(temp);
          continue;
        }
        applied.push(change);
      }
    }
  } catch (error) {
    const rollbackErrors: unknown[] = [];
    for (const change of applied.reverse()) {
      try {
        if (change.before && change.env) {
          const handle = await open(
            change.path,
            constants.O_WRONLY | constants.O_NOFOLLOW,
          );
          try {
            await handle.truncate(change.before.length);
            await handle.sync();
          } finally {
            await handle.close();
          }
        } else if (change.before) {
          // rename restores readonly generated files without needing write access to the old inode.
          const temp = `${change.path}.${randomUUID()}.rollback`;
          temps.push(temp);
          const handle = await open(temp, "wx", change.mode);
          try {
            await handle.writeFile(change.before);
            await handle.sync();
          } finally {
            await handle.close();
          }
          await rename(temp, change.path);
        } else await rm(change.path, { force: true });
      } catch (rollbackError) {
        rollbackErrors.push(rollbackError);
      }
    }
    if (rollbackErrors.length)
      throw new AggregateError(
        [error, ...rollbackErrors],
        "Generation failed and rollback was incomplete; inspect file permissions and destinations.",
      );
    throw error;
  } finally {
    for (const temp of temps) await rm(temp, { force: true });
    for (const dir of dirs.reverse()) await rmdir(dir).catch(() => {});
  }
  return changes.map((change) => change.path);
}
